{"code": "import pandas as pd, numpy as np
df = pd.read_csv('data.csv', parse_dates=['date'])
a = df[df.account_id=='e0yOWue']
fam = a.pivot_table(index='date', columns='instance_family', values='unblended_cost', aggfunc='sum').fillna(0)
app = a.pivot_table(index='date', columns='application', values='unblended_cost', aggfunc='sum').fillna(0)
def cyc(p,c):
    s=p[c].values
    res={}
    for lag in [3,7]:
        pred=np.roll(s,lag); pred[:lag]=np.nan
        m=~np.isnan(pred)&(pred>5)
        r=(s[m]-pred[m])/pred[m]
        mu,sd=np.nanmean(r),np.nanstd(r)
        z=( (s[-6]-mu*pred[-6])/(sd*pred[-6]) ) if pred[-6]>0 else float('nan')
        res[lag]=(round(mu,3),round(sd,3),round(z,2))
    print(c,res)
for c in ['oAYMdj0PDJ','vQexwxMSgl']: cyc(fam,c)
for c in ['nI7','CHi','lv8','4IG']: cyc(app,c)
